# coding: utf-8
"""
Elin Italian Localization - kettle.xlsx (Drama Kettle / Eludin / Sorin Arc)
Translates the entire epic storyline of Kettle (Eludin, the First Alchemist),
Quruitzia, Sorin (Issizzle), Demitas, Loytel, and the Crypt of the Damned.
"""

import os
import openpyxl

MOD_DIR = os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))
KETTLE_FILE = os.path.join(MOD_DIR, 'Lang', 'IT', 'Dialog', 'Drama', 'kettle.xlsx')

KETTLE_TRANSLATIONS = {
    8: "Riesci a udire le antiche parole che il vento sussurra? Vago per questo mondo per apprendere i racconti che il vento porta con sé.",
    10: "Avrei delle domande da porti.",
    15: "Posso esserti d'aiuto in qualche modo?",
    16: "Riguardo alle pietre magiche",
    17: "Riguardo alla bottega di duplicazione",
    18: "(Indietro)",
    22: "Alcune leggende sulle pietre magiche riposano tra gli antichi manoscritti della Biblioteca Reale di Palmia.\n\nSi narra che Palmia possedesse un tempo tre potenti pietre magiche: la Pietra del Sovrano, la Pietra del Saggio e la Pietra del Folle. Questi manufatti portarono immensa prosperità al regno, ma vennero allontanati per sigillare un segreto per sempre durante il regno di re Zashim. Furono affidati agli esseri più potenti e temibili.\n\nUno all'antica stirpe reale, uno al drago d'acciaio e uno al necromante corrotto.",
    23: "Cosa sia stato di quelle pietre e quale fosse il segreto che re Zashim tentò di proteggere rimane tuttora un mistero. Molti studiosi e alchimisti hanno cercato di svelare la verità, ma le risposte sono sfuggenti come sabbia dispersa dal vento.\n\nForse, un giorno, un avventuriero come te potrebbe essere colui che risolverà questo enigma.",
    27: "La mia bottega di duplicazione? Sì, l'ho aperta nella speranza di esserti d'aiuto nelle tue avventure.\n\nL'antica alchimia tramanda raffinate tecniche per replicare le proprietà intrinseche della materia. Sebbene non sia possibile riprodurre ogni singolo manufatto, posso replicare oggetti che hai già fabbricato con le tue mani, o persino sementi rare.",
    28: "Se c'è qualcosa che desideri duplicare, affidalo alle mie cure. Ci vorrà un po' di tempo, ma farò in modo di produrne copie con regolarità per te.\n\nA proposito: il numero massimo di articoli che posso duplicare e vendere dipende dalla scala e dalle risorse della mia bottega. Mi dispiace chiedertelo, ma se ti occorrono più manufatti duplicati, investire nella bottega mi darebbe una mano preziosa.",
    34: "Sembri turbato, Loytel. C'è qualcosa che ti angustia?",
    35: "Kettle, la tua apprendista è una ragazza davvero intrattabile...",
    36: "Apprendista? Ah, Quruitzia non è affatto mia allieva. In verità, detesta l'alchimia con tutto il cuore.",
    37: "Oh? E per quale motivo?",
    38: "Perché sua madre era un'alchimista.",
    39: "...",
    41: "La madre di Quruitzia era una mia cara amica. Un'alchimista che viveva in un modesto villaggio, una studiosa devota e appassionata. Ma, come spesso accade, gli abitanti non riuscivano a comprenderla.\n\nI superstiziosi popolani la evitavano chiamandola strega. E in quanto figlia della 'strega', Quruitzia è sempre stata ostracizzata dagli altri bambini. I suoi occhi, naturalmente di colori diversi, venivano temuti come 'occhi della sciagura'.",
    42: "Dopo che la madre morì a causa di una malattia, Quruitzia fu affidata alla chiesa del villaggio, dove continuò a essere trattata come una reietta. Un giorno, arrivò a cavarsi un occhio da sola nel disperato tentativo di dimostrare la propria innocenza.\n\nQuando visitai quel villaggio, trovai Quruitzia ormai morente sul pagliericcio di un capanno fatiscente ai margini dell'abitato. Usai l'alchimia per strapparla alla morte, e quell'atto legò per sempre i nostri destini. Ecco perché continua a viaggiare al mio fianco.",
    43: "Che storia straziante... Essere tacciata di stregoneria solo per occhi di colore diverso, che follia inconcepibile!",
    44: "Vorrei darti ragione, eppure, a volte, certi 'poteri' primordiali si manifestano proprio accompagnati da simili anomalie.\n\nNon ti ho narrato il suo passato per parlare di tragedie o dell'ottusità dei popolani.",
    45: "Quel giorno... ciò che mi accolse al mio arrivo al villaggio fu un silenzio spettrale, un eccidio dove ogni creatura vivente era perita. Se sia stata opera del suo 'potere' o meno, non so dirlo. Ma Loytel, e tu, #pc, tenetelo bene a mente.\n\nQuella fanciulla è nata sotto l'influsso di un potere peculiare, e quel potere influenzerà inesorabilmente il destino di chiunque le stia intorno.\n\nSe mai doveste desiderare che ce ne andiamo, non avete che da dirlo.",
    46: "Oh, Kettle...",
    59: "Non spira un filo di vento, è una notte stranamente silenziosa. Sei lì nell'ombra, non è vero, Demitas?",
    60: "Eh... impossibile celarsi al tuo sguardo.",
    61: "Sei sempre lo stesso, Eludin... perlomeno nelle tue sembianze.\n\nAnche ora, ridotto a ciò che sono, parlare con te mi riporta alla mente i giorni in cui ero ancora un essere umano.",
    62: "Quando eri un essere umano, eh? Già...\n\nDel resto, hai sempre avuto l'abitudine di ficcare il naso ovunque.",
    63: "Vagare notte dopo notte attorno ai miei compagni, instillando strane storie nelle loro menti... è proprio da te.\n\n...Ma è solo per questo? Ti stai intromettendo troppo negli affari di quella fanciulla.",
    64: "Hehehe... Soltanto la premura di un vecchio.",
    66: "Quella ragazza è un pericolo. Tu sai bene cosa dimora nel suo sguardo.\n\nColei dagli occhi infausti è il ricettacolo della pietra... E persino adesso, la pietra magica che dorme nel cucciolo di drago brama il proprio ricettacolo.",
    67: "Demitas, apprezzo la tua preoccupazione. Ma finché le sarò accanto, la pietra magica non si risveglierà.",
    70: "Comprendo. Se lo afferma il \"Primo Alchimista\", dev'essere senza dubbio la verità.",
    72: "Hehehe...",
    74: "...Ciò nonostante, Eludin, il destino troverà Quruitzia e Corgon.",
    76: "La diceria di un cucciolo di drago che vive tra i mortali si spargerà presto su ogni bocca. Naturalmente nessuno oserebbe levare la mano contro un drago... salvo uno.",
    77: "...",
    79: "C'è colui che conosce la leggenda secondo cui la pietra magica fu donata al Drago d'Acciaio ai tempi di re Zashim; colui che dalla morte del drago cerca disperatamente la pietra perduta.\n\nEgli udrà del cucciolo e ne intuirà all'istante l'inestimabile valore.\n\nEgli darà la caccia a Quruitzia e Corgon senza requie.",
    80: "...Issizzle.",
    81: "Proprio così, \"Issizzle\", l'abominio delle tenebre.\n\nUn tempo possente incantatore di grande fama, ora una ripugnante creatura ghermita dalla brama della pietra magica, sprofondata nell'oscurità... Il tuo compassionevole discepolo, che non fosti capace né di uccidere né di salvare.",
    82: "...",
    83: "Cosa intendi fare con quella fanciulla?\n\nAlla fine, o diverrà la schiava della pietra, o verrà manipolata da lui, o verrà trucidata...",
    84: "Non distogliere lo sguardo dalla verità, \"Kettle\".\n\nNon v'è salvezza per quella ragazza. Sei sull'orlo di ripetere il medesimo fatale errore. E la tua indulgenza porterà ancora una volta la calamità su questo mondo.",
    99: "Amici miei, posso rubarvi qualche istante?",
    100: "Mokyu?",
    101: "Che succede, Kettle? A quest'ora della notte?",
    102: "C'è una minaccia che si sta profilando all'orizzonte.\n\nVoglio che ne siate tutti al corrente. Di un uomo che un tempo fu mio apprendista, e del potere che arde sopito nello sguardo di Quruitzia...",
    107: "Capisco... Mi sembra che la testa stia per scoppiarmi.\n\nIl sangue di un'antica strega che scorre nelle vene di Quruitzia, e la Pietra Magica celata nel piccolo corpicino di Corgon...?",
    108: "Se ciò che dici corrisponde al vero, Kettle, e se Issizzle sta venendo per ghermire la Pietra... dobbiamo prepararci immediatamente. Dobbiamo fare scudo attorno a Quruitzia e Corgon.",
    110: "Hehehe...",
    111: "E rieccoti qui. Cos'hai da sghignazzare in quel modo?",
    112: "L'incolumità della ragazza e del cucciolo di drago non hanno la minima importanza.\n\nIl mondo stesso mostra i presagi della propria fine, proprio a causa della loro stessa esistenza.",
    113: "Cosa intendi dire con queste parole, Demitas?",
    114: "La loro stessa natura... gli Antichi non recano altro che rovina e stasi a questo mondo. La loro immane potenza è sorgente di distorsione, e il loro fulgore divora nelle fiamme tutto ciò che li circonda.",
    115: "Il significato che con fatica ci sforziamo di edificare viene calpestato dalle loro leggi supreme come fosse polvere al vento. Impotenti e tremanti, diventiamo meri burattini costretti ad assistere al dispiegarsi del fato. Che queste entità lo vogliano o meno, il risultato non cambia. Quale progresso potrà mai germogliare in un mondo simile?\n\nÈ per questa ragione che gli dèi hanno cessato di immischiarsi nelle vicende dei mortali e hanno abbandonato la terra. E gli Antichi... i figli plasmati dagli dèi dovrebbero seguire il loro supremo esempio.",
    116: "...Eh?!",
    117: "In verità, questo mondo non ha alcun bisogno di Issizzle, né tantomeno di un cucciolo di drago o di una strega. Sarebbe mille volte meglio se svanissero nell'oblio.\n\nHai forse dimenticato la calamità che la tua misericordia ha scatenato, Kettle? Avresti dovuto sopprimere Issizzle. E dovresti togliere di mezzo anche questa fanciulla e il cucciolo di drago.",
    118: "...",
    120: "Ehi, un momento, frena la lingua! Non posso lasciar correre simili parole.\n\nChi diavolo ti credi di essere per disporre con tanta arroganza della vita di questi ragazzi?",
    121: "Quruitzia è un'entità letale. Tu stesso lo sai bene. L'Occhio Infausto di quella fanciulla ha portato lo sterminio su un intero villaggio. E quel potere non si è ancora neppure \"risvegliato\".",
    122: "Ma cosa ha fatto scattare quel potere? Non sono stati forse i superstiziosi abitanti a spingere Quruitzia sull'orlo del baratro?\n\nNon era neppure conscia del potere che celava in sé. Accusarla per una simile sciagura è una crudeltà inaccettabile!",
    123: "Dunque, per pura compassione verso questa fanciulla, non ti importerebbe se l'intero mondo finisse in cenere?",
    125: "B-beh, ecco...",
    129: "...A me non importerebbe affatto. Se questo mondo ripudia l'esistenza di Quruitzia in virtù di simili sofismi, allora tanto vale che finisca in rovina!",
    130: "Mokyu!",
    131: "M... Milady Farris, non le sembra di spingersi un po' troppo oltre...?",
    132: "Niente affatto, messer Loytel. Quruitzia è una compagna a noi immensamente cara. Farò tutto il necessario per proteggerla, anche a costo di sfidare le leggi dell'universo!\n\n...Non è forse così, messer Loytel?",
    133: "M...",
    134: "Ma certamente!\n\nAncora una volta le vostre parole mi hanno aperto gli occhi, milady Farris!",
    135: "Il destino del mondo o simili sciocchezze non sono affari che mi riguardano!\n\nIl destino di Quruitzia spetta solo a lei deciderlo, e non permetteremo a nessuno di imporglielo: né a Issizzle, né a chicchessia!\n\nQuesto è quanto. Com'è ovvio e giusto che sia!",
    136: "Mokyu!",
    137: "E poi, Demitas, non osare paragonare Quruitzia a mostruosità pericolose come Issizzle quando blateri di 'Antichi'!\n\nQuesti due passano l'intera giornata a farsi le coccole e a chiamarsi a vicenda \"Ma... mma...\" e \"Corgon♪\", lo sai benissimo!",
    138: "Farris... Loytel...",
    139: "...",
    140: "Sciocchi, trascinati dai sentimenti e sordi alla ragione... Ed è così che gli stessi errori vengono eternamente perpetuati.\n\nVoi non sapete. Non sapete quale sofferenza vi sia nel non poter salvare né uccidere. La vostra mollezza non recherà altro che nuovo, straziante dolore a quella fanciulla!",
    141: "Demitas... È lei, non è così? ...Stai ancora pensando a Telessia.",
    142: "Telessia...? Lei... Heh, comprendo... Hehehe... Dunque è così.",
    143: "Hehehe... Rivedere la sua ombra in lei... Proprio io, tra tutti...",
    144: "Ebbene, suppongo che dobbiamo ancora imparare a conoscerci a fondo. Ma a questo rimedierà il tempo.\n\nPer il momento, uniamo le nostre forze e studiamo un piano per respingere Issizzle.",
    145: "Sono d'accordo con te, Loytel. Ho anch'io qualche idea a riguardo.\n\n...Ma forse dovremmo fermarci qui per stanotte. L'alba è ormai alle porte.",
    146: "Heh, e pensare che ci è voluta un'intera notte per arrivare a una conclusione così ovvia!\n\n#pc, hai ascoltato tutto, vero? Pare proprio che da adesso in poi avremo un bel po' di lavoro da sbrigare.",
    159: "- Antica Torre -",
    161: "...Sorin, sei davvero tu? Quanti secoli sono trascorsi dal nostro ultimo incontro.",
    162: "Ti ricordi ancora di me?",
    163: "(parole antiche, incomprensibili)",
    164: "...",
    165: "(parole antiche, incomprensibili)",
    166: "Ne sono sbalordito. Dunque tu ancora...",
    167: "(parole antiche, incomprensibili)",
    168: "Hai atteso? ...Hai atteso me?",
    169: "...",
    173: "...",
    174: "Umpf, abbastanza vicino. È trascorso molto tempo dall'ultima volta che ho assunto queste sembianze.",
    175: "Ebbene, questo vi rende più agevole conversare, Maestro?",
    176: "È un sollievo, Sorin... sapere che rammenti ancora chi fosti un tempo.",
    177: "Che amara ironia. Che io ricordi o meno questo vecchio volto, non ho mai posseduto l'umanità che avete sempre sperato di scorgere in me.\n\n...Poco importa. Non ho alcun desiderio di guastare una rimpatriata attesa due secoli. Sediamoci e parliamo qui, come facevamo un tempo in questa tetra stanza... del cristallo che chiamiamo la Pietra Magica.",
    178: "A quanto pare avevi previsto il mio arrivo... e il motivo che mi conduceva a te.",
    179: "...Il Drago d'Acciaio, \"Corgon\". Un tempo ricevette una Pietra Magica dal Re di Palmia. L'uccisore di draghi \"Thorran\" abbatté quella bestia circa vent'anni fa. Eppure quel folle fece ritorno a mani vuote, e il fato della Pietra sprofondò nell'oblio.\n\n...Finché, pochissimo tempo fa, voi non avete scoperto l'ultimo discendente di Corgon.",
    180: "Il giorno stesso in cui quella diceria giunse alle mie orecchie, scovai il rifugio del cucciolo. Sarebbe stato un gioco da ragazzi sopprimerlo e strappargli la Pietra all'istante. Ma ho scorto voi al fianco della creatura.\n\nCosì ho scelto di attendervi in questa torre. Sapevo che sareste venuto.",
    181: "Ora ditemi, Maestro: cosa intendete fare di quel piccolo drago... e della Pietra incastonata nella sua carne?\n\nUn tempo acconsentiste al mio piano, benché siano trascorsi secoli da allora. Cosa ha mutato il vostro cuore nel frattempo? Siete venuto a me senza il cucciolo, il che significa che non avete alcuna intenzione di offrirmi il vostro aiuto.",
    182: "Hai ragione, non posso consegnarti Corgon. Ma prima che ti spieghi il perché, rispondimi, Sorin. Stai ancora portando avanti le tue ricerche sulla Pietra Magica?",
    183: "Heh. Ma certamente. Per quale altro motivo dovrei vincolare la mia anima a questa carne putrescente che chiamano \"abominio delle tenebre\"... e languire nel buio di una torre decrepita?",
    184: "Devo svelare il segreto supremo della Pietra.\n\n...Gli dèi sono partiti, e il mistero sta svanendo dal mondo. Tutti gli \"antichi esseri\" vanno incontro a una lenta estinzione. Il che equivale a dire che la magia stessa perirà.\n\nSì, ho assoluto bisogno della Pietra. Per preservare il mondo nello stato in cui è fiorito c'è una sola via: sfruttare il potere della Pietra e richiamare gli dèi sulla terra.",
    196: "- Antica Torre -",
    198: "Come ben sapete, gli \"antichi esseri\" e la fonte primigenia di ogni arcano — la magia stessa — stanno svanendo dal creato.\n\nChe avvenga tra un secolo o tra un millennio, non so dirlo. Ma dalla notte in cui gli dèi si ritirarono dalla terra, un fato ineluttabile è stato segnato sopra di noi.",
    199: "Proprio così... Col tempo, il mito diventerà la fiaba della buonanotte di un vecchio cantastorie, e gli spiriti esisteranno solo nei libri illustrati.\n\nMa ti sei mai fermato a riflettere su questo: forse il mondo sta semplicemente tornando alla sua forma originaria.",
    200: "La sua forma originaria... ottusa, brutale, priva di qualunque valore per cui valga la pena vivere.\n\n...I presagi sono già fin troppo evidenti. L'antica civiltà Eulderna che un tempo dominava Sierre Terre ha smarrito la sua gloria. A oriente sorge il Nuovo Regno di Yel, che innalza la scienza come suo stendardo. La magia viene declassata a 'mera disciplina accademica', e molte delle stirpi più antiche verranno condotte dagli umani all'estinzione o alle catene.",
    201: "Sì, l'era dei mortali è alle porte. E la storia di questo pianeta parla chiaro: come su Eyth Terre e Rem-Ido, l'umanità corre a precipizio verso la propria rovina... senza comprendere il valore di ciò che saccheggia e distrugge lungo la via.",
    202: "Ogni civiltà incontra il proprio tramonto. Dove qualcosa appassisce, qualcos'altro germoglia di nuovo. Non credi che sia una legge cosmica che trascende le nostre piccole misure di bene e male, Sorin?",
    203: "Basta con gli indovinelli. Parlerò chiaro.\n\nL'ascesa e la caduta dei mortali, il bene e il male... persino i disegni degli dèi: nulla di tutto questo mi importa minimamente! Io rifiuto categoricamente di perdere questo potere. Questa stregoneria che un tempo piegava il mondo al mio volere è tutto ciò che sono. Esserne privato mi è intollerabile.",
    204: "...Maestro, perché mi avete risparmiato duecento anni fa? Credevo fossimo sulla medesima nave.\n\nO siete forse giunto oggi per portare a compimento ciò in cui falliste allora? Badate bene: il mio potere è cresciuto... di gran lunga oltre il vostro.",
    205: "Le Pietre Magiche, forgiate a quanto si dice dagli dèi nell'era delle origini... se ne afferriamo il pieno potenziale, potremo spalancare i portali divini e richiamarli indietro, arrestando la degradazione del mondo.\n\n...Io ucciderò il cucciolo di drago e prenderò la Pietra. Provate a fermarmi se volete: non vi servirà a nulla.",
    206: "Sorin... su una cosa sei profondamente in errore.",
    207: "In errore...?",
    208: "Le tue ricerche sulla Pietra sono già concluse. Credo che tu ne abbia già estratto tutto ciò che essa poteva offrirti.",
    209: "Concluse? Non dite assurdità! Il potere della Pietra trascende ogni cosa...",
    210: "Tu possiedi già il potere della Pietra. Ma — come tu stesso devi aver intuito dentro di te — ahimè, anche se radunassi le altre due Pietre, la forza che brami giacerebbe ancora infinitamente oltre la tua portata.",
    211: "Ah! E cosa potreste mai saperne voi, Maestro... privo come siete di una Pietra?\n\nÈ vero, un tempo possedevate un sapere arcano sconcertante su di esse. Ma era tanto tempo fa. Siete rimasto indietro di due secoli rispetto a ciò che ho appreso io.\n\nIl potere occulto della Pietra spalancherà la soglia divina e richiamerà gli dèi...",
    212: "...Se si trattasse di un'autentica Pietra Magica, sì. Ma ciò che stringi tra le mani non è che una contraffazione.",
    213: "Sciocchezze... Heh... Non sarete certo venuto fin quassù solo per propinarmi simili fandonie?",
    214: "Sorin, quella Pietra l'ho forgiata io.",
    215: "...",
    216: "Maestro, da quando vi abbassate a battute così tristi...?",
    217: "Non ti biasimo se dubiti.\n\nAllora guarda dentro questo occhio, Sorin... guarda la maledizione impressa nella mia cavità, la maledizione che non ha mai fine.",
    222: "...!!",
    223: "Devi aver udito la leggenda del 《Cristallo di Pietra di Aura》. Questa è la sola, autentica Pietra Magica, Sorin.\n\nLe pietre che tu e Corgon custodite non sono che fallimenti da me fabbricati in epoche remote, rozze imitazioni create a somiglianza di questo cristallo.",
    224: "Assurdo... Il 《Cristallo di Pietra di Aura》... l'Occhio Eterno...? Quello è solo un mito...",
    225: "Un mito... è... reale...? Allora...",
    226: "Ah... hehehe... E pensare che non me ne ero mai avveduto... Dunque... stanno così le cose...",
    227: "\"Il Primo Alchimista\". Ma certo... voi eravate il principio di tutto.\n\nMolto prima che l'umanità di quest'era emettesse il suo primo vagito, voi già camminavate sulla terra. No, forse è più esatto dire che non potevate morire. Ora comprendo ogni cosa: il segreto del vostro occhio e la ragione per cui non mi uccideste.\n\nPrego, sedetevi, Maestro. A quanto pare abbiamo ancora molto di cui discutere.",
    239: "- Antica Torre -",
    241: "Dunque quel racconto corrispondeva a verità, non è così?\n\n...Ai tempi in cui ella era ancora uno spirito dei boschi, il suo nome era Aura.\n\nSi innamorò di un mortale e si fece prigioniera di propria volontà in una dimora di pietra. Col tempo spiegò le ali assieme a un fanciullo che agognava il firmamento e fu elevata a divinità. Sì, la leggenda della nascita di Lulwy.",
    242: "È un mito celebre, ma pochissimi tomi tramandano quale sorte toccò all'uomo mortale in seguito.\n\nUna cronaca afferma che Aura — no, Lulwy — scagliò su di lui una condanna spietata. Come punizione per essersi abbandonata all'amore di un cuore umano, gli strappò entrambi gli occhi affinché non potesse mai più contemplarla, e gli impose la maledizione dell'immortalità. Sapeva che quell'uomo avrebbe continuato ad amarla... e che per questo avrebbe patito un tormento eterno.",
    243: "...L'ascensione di Lulwy appartiene alle ere remote, a ciò che chiamano 'l'Era del Principio', la Seconda Era. Quanti millenni sono trascorsi da allora? Decine di milioni... centinaia di milioni di anni?\n\nHeh, che meraviglia inaudita... Maestro, a quanti dei segreti dispersi di questo mondo siete rimasto indissolubilmente legato?",
    244: "Una sola cosa è certa: non sono esperienze che alcuno dovrebbe mai invidiarmi.\n\nAnche quella leggenda... fui probabilmente io stesso a metterla per iscritto, sebbene dubiti che sia giunta fino a te senza alterazioni.",
    245: "Sì, mi capitò di scorgere la sua figura in quella foresta, ormai ascesa a divinità.\n\nNell'istante in cui volse lo sguardo verso di me, questo cristallo si impresse nella mia cavità oculare. Non vi fu emozione, non vi fu parola, nulla di nulla. Da allora ho vagato in una notte eterna, implorando la sua voce... ma ella non si è mai più mostrata al mio cospetto.\n\nQuesto occhio non è una solenne punizione: fu unicamente un suo mero capriccio. Per Lulwy, divenuta dea, io non sono più di un granello di polvere disperso nel vento.",
    246: "...Ciò nonostante, quest'occhio rappresentava il mio solo legame con lei. Custodivo la debole speranza che, se ne avessi decifrato il segreto, avrei potuto attirare di nuovo la sua attenzione. Giorno e notte ho inseguito l'enigma della pietra, e quell'ardore mi spinse infine al tentativo di ricrearla.",
    247: "Senza che me ne rendessi conto, venni annoverato tra i più grandi alchimisti della storia. Ma l'ingegno dei mortali non può eguagliare i prodigi degli dèi. Nessuna delle innumerevoli pietre che ho forgiato possedeva il vero potere di quest'occhio.\n\n...Alla fine abbandonai l'impresa, e quelle pietre contraffatte sprofondarono tra le ceneri della storia.",
    248: "...Eppure, i tre frammenti che avete forgiato hanno resistito all'usura del tempo, e sono riemersi in quest'era. Non è forse così?",
    249: "...Sì. È proprio così.",
    250: "Quando il vostro discepolo entrò in possesso di una Pietra Magica e cadde preda del suo oscuro potere, voi raggiungeste la sua torre. Premuroso e compassionevole Maestro quale siete, veniste per uccidermi... per dare pace alla mia anima.\n\nMa... quando scopriste il mio disegno, un lacerante dilemma mise radici nel vostro animo.",
    251: "Pensaste che, se la mia immensa stregoneria si fosse unita alla Pietra, forse gli dèi avrebbero potuto davvero essere richiamati sulla terra.\n\nE che forse avreste potuto riabbracciare Lulwy, e apprendere il vero significato della maledizione che grava sul vostro sguardo.",
    252: "...Il significato di quest'occhio. Persino quello, credo, ormai non ha più alcuna importanza.\n\nSorin, io desideravo soltanto rivedere Lulwy ancora una volta.",
    253: "...",
    254: "Heh... hehehe... Maestro, sembra che finalmente abbiamo trovato ciò che ci accomuna.\n\nNel profondo del vostro petto cova una fiamma oscura che né la ragione né la morale riescono a estinguere. Proprio come me, c'è qualcosa che bramate con tale disperazione da non poterlo lasciare andare... incurante di come il mondo ne verrebbe stravolto.",
    255: "...E la vittima di quell'ardore proibito fu questo mio misero corpo, non è vero?\n\nDegradarmi a un mostruoso abominio pur di inseguire una pietra contraffatta... che farsa grottesca.",
    256: "...Ti chiedo perdono, Sorin.",
    257: "No, Maestro.\n\n...L'ironia ha i suoi pregi. Questo corpo corrotto non è servito solo a prolungare la mia infima esistenza.\n\nOra che la via della Pietra è sbarrata, la conoscenza ottenuta attraverso questa carne mutata potrebbe rivelarsi la mia ultima speranza.",
    258: "Cosa intendi dire con questo, Sorin?",
    259: "Vi sono segreti nel reame dei morti che non vengono mai sussurrati tra i vivi.\n\nMa prima, un punto da chiarire. Ora che le Pietre si sono rivelate meri simulacri, non ha più alcun senso per me impadronirmi di quella del cucciolo di drago. O 'quasi' alcun senso. Perché l'altra Pietra stuzzica ancora la mia curiosità.\n\nE poiché ho la forza di strapparvela se lo volessi, credo di avere ancora una carta vantaggiosa da giocare per la trattativa.",
    260: "Dunque, stai dicendo che vorresti chiedermi un favore, non è così?",
    261: "Sono lieto di avere a che fare con un uomo d'intelletto. Si tratta di una commissione semplicissima.",
    262: "A breve distanza da questa torre, nell'acquitrino, si apre una caverna da cui chiunque si tiene alla larga: la chiamano la \"Cripta dei Dannati\". Nelle sue viscere giace una \"pozza di putrescenza\", sorvegliata dai non-morti... ma alla quale i morti stessi non possono mai accostarsi.\n\n...Prendete questa fiala.\n\nVoglio che lasciate cadere una singola goccia del liquido contenuto al suo interno dentro quella pozza. ...Ebbene, non è abbastanza semplice?",
    263: "Naturalmente, per scendere nelle profondità della Cripta dei Dannati avrete bisogno di un valido sostegno: consultatevi con l'avventuriero che vi accompagnava.\n\nHeh, quello sguardo insospettito è naturale... ma non posso rivelarvi altro di questo arcano.\n\nL'effetto di quella goccia non maturerà prima di svariati secoli: vi giuro che nessun male toccherà i vostri compagni. Consideratelo il prezzo per la vita del cucciolo di drago: non vi sembra un patto più che vantaggioso, Maestro?",
    264: "...",
    284: "...Guardate, è tornato Kettle!",
    285: "Mokyu?",
    286: "Bentornato tra noi, Kettle!",
    287: "Sono a casa, Quruitzia, Corgon.",
    288: "Hai un'aria preoccupata... Le cose sono andate male, dopotutto?",
    289: "No, non si tratta di cattive notizie. È solo che...\n\nBeh, potresti radunare tutti gli altri per prima cosa, Quruitzia?",
    290: "Mokyu...",
    295: "...ed è così che stanno le cose.",
    296: "Capisco. Quindi, in cambio della vita e dell'incolumità di Corgon, dobbiamo versare una singola goccia di quella fiala nella cosiddetta \"pozza di putrescenza\".",
    297: "Uhm... Naturalmente ci occorrerà l'aiuto di #pc per esplorare quella caverna, ma se versare quella goccia non comporta alcun pericolo immediato, non mi sembra un cattivo affare!",
    298: "No! Assolutamente no! Mescolare ciò che è contenuto in quella fiala con la \"pozza di putrescenza\" è una follia disastrosa!",
    299: "Milady Farris, ma...",
    300: "La prego di ascoltarmi, messer Loytel! C'è una malvagità innaturale annidata in questo patto.\n\nSulla Cripta dei Dannati aleggia un'antichissima e agghiacciante leggenda.\n\nTanto tempo fa, l'\"Impuro\" dimorava laggiù e officiava sacrifici così orrendi da far gelare il sangue nelle vene. Quell'abominio minacciò la terra e persino il reame celeste, finché gli dèi stessi non lo sterminarono! Tuttavia le sue carni e il suo sangue corrotto si sciolsero nelle profondità della caverna, formando una pozza nera come la pece che non si asciuga mai.\n\nMesser Loytel, quella pozza è qualcosa che le mani dei mortali non dovrebbero mai toccare!",
    301: "Un racconto spaventoso davvero... Ma un momento, credo di aver compreso il trucco!\n\nQuella singola goccia che dovremmo versare è un seme malefico destinato a germogliare tra secoli! Un male così colossale che gli dèi non potranno ignorare... un'esca per costringerli a tornare sulla terra! Dev'essere per forza così.\n\nIn effetti, se assecondiamo la richiesta di Issizzle, lasceremo in eredità ai posteri una maledizione spaventosa!",
    302: "...E tuttavia, stando a ciò che riferisce Kettle, Issizzle è un incantatore di una potenza inimmaginabile. Se respingiamo questo accordo, possiamo davvero difendere il piccolo drago con le nostre sole forze?",
    303: "Mokyu...",
    304: "No, non è affatto necessario rifiutare il patto. Ho un'idea geniale, messer Loytel!\n\nPortiamo con noi questa fiala al posto della sua!",
    305: "\"Al posto della sua\"? Che cos'è questa boccetta? A vederla somiglia come una goccia d'acqua a quella di Issizzle!",
    306: "Uhm... ma emana un profumo freschissimo e purissimo! È una sorta di acqua santa?\n\nMa certo: intendete purificare la pozza con una goccia sacra! Splendida trovata, milady Farris... anche se dove mai avete rimediato una cosa del genere?",
    308: "...",
    310: "In ogni caso, ha un profumo celestiale. Così candido, così fresco, quasi come... beh, come panni appena stesi e lavati...",
    311: "...",
    312: "...",
    313: "Forse farei meglio a non indagare oltre su cosa contenga. Non sta bene fare i ficcanaso. In ogni caso, è un piano brillante, milady Farris!",
    314: "Se non altro, una goccia di questa fiala non richiamerà alcuna divinità oscura in questo mondo!",
    315: "P-proprio così. Verissimo!",
    316: "...",
    317: "...",
    318: "Coff coff... Dunque, #pc.\n\nQuesta decisione è un fardello troppo gravoso per me solo: affido la scelta nelle tue mani.\n\nRecati alla Cripta dei Dannati e trova la \"pozza di putrescenza\". Giunto sul posto, potrai adoperare la fiala che ci ha consegnato Issizzle, oppure l'\"acqua santa\" che ci ha fornito milady Farris... la scelta spetta solo a te. Rifletti attentamente.\n\n...Non andrai da solo: verrò anch'io con te! Sarebbe ingiusto scaricare tutto il peso sulle tue spalle.",
    335: "Dunque è questa la famigerata \"Pozza\"...\n\nNera e torbida come la pece... a guardarla dentro sembra quasi sul punto di inghiottirmi!",
    336: "Che posto ripugnante e sinistro. Sbrighiamo questa faccenda per conto di Issizzle e andiamocene all'istante!",
    338: "Non potrei essere più d'accordo.\n\nBasta versare una singola goccia in questa \"Pozza\". Un compito da ragazzi.",
    340: "Allora, #pc, quale boccetta intendi usare? Quella sinistra e inquietante di Issizzle, oppure... l'acqua santa di milady Farris?\n\n(...#pc, mi senti?)\n\n(Milady Farris ha voluto seguirci per forza, ma non temere: qualunque sia la tua scelta, farò in modo che non se ne accorga. Rispetterò qualunque decisione prenderai!)",
    341: "Usa la fiala di Issizzle.",
    342: "Usa la fiala di Farris.",
    344: "...La fiala di Issizzle, confermi?\n\nPuzza di marciume e corruzione lontano un miglio. Questa singola goccia nutrirà senza dubbio qualcosa di mostruoso.",
    345: "Sì.",
    346: "No.",
    348: "...La fiala di milady Farris, confermi?\n\nEmana un profumo... delizioso. Non riesco nemmeno a immaginare cosa produrrà una singola goccia di questa roba.",
    349: "Sì.",
    350: "No.",
    355: "D'accordo. Vado a versare una goccia da questa fiala dentro la \"Pozza\".\n\nNo, #pc, lascia che faccia almeno questo! Non posso permettere che sia tu a sobbarcarti tutti i rischi da solo.",
    356: "...Pensare che una singola goccia possa cambiare il fato del mondo intero... mi toglie quasi il fiato.\n\nE poi questo pavimento è viscido da morire e...",
    358: "Aaaaagh!!",
    360: "...",
    361: "...",
    364: "C-calma, sto bene, non mi sono fatto niente!\n\n...Fiuuu. Sono inzuppato da capo a piedi e fa un ribrezzo tremendo, ma almeno la \"Pozza\" non era così profonda.\n\nUn momento... dove sono finite le due boccette?!",
    365: "...Messer Loytel...!!",
    366: "Milady Farris, mantenga la calma...",
    367: "Dietro... dietro di voi!",
    376: "...RU=VA SHE=NUR AZZALUU=RU... NE=IF DALOON... SA=RA KUN=AGRA...\n\n...RU=VA SHE... L'E=NOR SHA=RAGUN... HA=ZA...!!",
    377: "C-cosa?!",
    378: "Non ho la più pallida idea di cosa stia blaterando, ma ha l'aria di essere furioso oltre ogni dire!",
    379: "...RU=VA ZA=NOO=LE... AG=SHE... AGSHENE... I=DRA... SHA=LA FUN...!!",
    380: "L'Impuro, Azrasizzle... l'antico dio del male sigillato un tempo dagli dèi stessi...!",
    381: "...Dunque è questa la vera natura della \"Pozza\": un seme di calamità in attesa di schiudersi! Perfetto, lo sradicheremo qui e ora!\n\nHeh... persino un dio del male non riuscirà a scatenare la sua piena potenza con un profumo così fresco addosso!\n\nAvanti, #pc! Il resto lo affido a te!",
    392: "Magnifico colpo, #pc!",
    393: "Un'impresa straordinaria, milord #player!",
    394: "Quando quell'abominio è balzato fuori ho creduto davvero che per noi fosse finita... ma alla fine, in un modo o nell'altro, le cose si aggiustano sempre!",
    395: "Issizzle... quel dannato disgraziato. Anche se la catastrofe si sarebbe compiuta in un futuro lontano, è inconcepibile che volesse liberare un simile orrore per pura ambizione personale!\n\nMa ora sorge un bel grattacapo: non possiamo più mantenere la parola data.",
    396: "Noi non abbiamo visto nulla, e qui non è successo assolutamente niente... Non è così, messer Loytel?",
    397: "...Esattamente. Dubito che se la berrà con facilità, ma è l'unica versione che possiamo sostenere.\n\nD'accordo. Torniamo alla nostra dimora e attendiamo l'arrivo di Issizzle.",
    410: "Kettle... posso parlarti un momento?",
    411: "Dimmi pure, Quruitzia.",
    412: "Poco fa... ho visto un ragazzino con una veste nera che non avevo mai visto prima. Fissava intensamente me e Corgon. Ho provato a parlargli, ma Demitas è piombato lì furibondo e ha iniziato a litigare con lui...",
    413: "Capisco... Immaginavo che si sarebbe fatto vivo a momenti.\n\nQuel ragazzo vestito di nero è Sorin: la forma umana di Issizzle. Tra lui e Demitas c'è... un passato complicato.",
    414: "Quel ragazzo... è Issizzle?!",
    415: "Non hai nulla da temere, Quruitzia. Abbiamo tenuto fede al patto stipulato nella Cripta dei Dannati.\n\nNon è vero, Loytel?",
    416: "...Beh, ecco, Kettle...",
    417: "Sì?",
    418: "N-niente... Sono certo che il pericolo sia scongiurato, ma tanto per sapere: cosa succederebbe se qualcuno facesse infuriare Issizzle?",
    419: "È un mago abbastanza potente da spazzare via un intero regno da solo. In quest'era, è sicuramente l'ultima persona al mondo che vorremmo provocare.\n\nMa non allarmarti, Loytel. Perché, <b>se avessi fatto qualcosa per farlo infuriare</b>, a quest'ora staresti già riposando tre metri sotto terra, eheheh.",
    420: "...A-ahahah... C-capisco...!",
    421: "(sottovoce) Milady Farris... qualunque cosa sia successa nella \"Pozza\", dobbiamo tacerla nella maniera più assoluta. Persino Kettle comincia a insospettirsi.",
    422: "(sottovoce) Sì, messer Loytel... È un peccato mortale non poterci comporre una ballata, ma stavolta dobbiamo cucirci la bocca.",
    423: "...Bene. A quest'ora Demitas si sarà calmato. Andiamo a sentire cosa ha da dirci.",
    429: "...",
    430: "...Dunque posso presumere che il patto sia stato adempiuto senza intoppi?\n\nNon temete, è solo una conferma. Ho percepito all'istante l'interferenza con la \"Pozza\". Tuttavia...",
    431: "Tuttavia...?",
    432: "Da quel preciso istante, una porzione della mia magia è andata perduta. Per l'esattezza, ho perso il corpo immortale di Issizzle.\n\nHeh, ma questa è, di per sé, la prova più gradita che la \"Pozza\" ha ricominciato ad agitarsi.\n\nNon v'è motivo di preoccuparsi: man mano che la potenza di quell'essere crescerà nella \"Pozza\", anche le mie arti magiche torneranno a fluire.",
    433: "...",
    434: "Hai perso parte del tuo potere? Che meravi— volevo dire, che terribile sciagura!\n\nDunque questo significa che Corgon e Quruitzia sono definitivamente fuori pericolo?",
    435: "…Maestro, fareste bene a spiegarglielo a dovere più tardi, affinché persino lo sciocco qui presente comprenda quale peso abbiano le parole per un mago.\n\nHo deciso di rispettare il patto pattuito, sebbene possieda ancora la magia sufficiente a trasformare questo luogo in una landa desolata in questo preciso istante, solo perché quell'idiota mi ha irritato.",
    436: "...Poco importa. In ogni caso, dubito che rivedrò mai più la maggior parte dei presenti qui riuniti.\n\nAver contemplato rarità come un cucciolo di drago e una strega, e aver scambiato parole così cortesi con un vecchio amico... direi che è valsa la pena di fare questo viaggio.\n\nE ora, Maestro.",
    437: "...Sorin, intendi davvero fare ritorno a quella tetra torre con il tuo... corpo attuale?\n\nSenza offesa, ma l'ultima volta che ho visitato la tua dimora non mi è parso affatto un posto in cui un \"essere umano\" possa sentirsi a proprio agio.",
    438: "...",
    439: "Eheh, non fare quella faccia truce. Lascia che te lo chieda in un altro modo.\n\nPerché non rimani a vivere qui con noi finché la tua magia non sarà tornata, Sorin?",
    440: "(prende un profondo respiro)",
    441: "(prende un profondo respiro)",
    442: "...",
    443: "Questa è... una proposta del tutto inaspettata, Maestro.",
    444: "...E al tempo stesso assai conveniente per me.\n\nIl significato dietro l'incontro tra il cucciolo di drago e la strega, l'avventuriero guidato dai fili del destino, e soprattutto voi, Maestro... Da quando ho appreso il segreto della pietra magica, la vostra stessa esistenza non smette di stuzzicare la mia curiosità insaziabile.",
    445: "Naturalmente, non ho alcuna intenzione di scroccare alloggio gratuitamente.\n\nCosa desiderate in cambio della mia permanenza? Un grimorio perduto dell'era antica, un elisir di eterna giovinezza, o magari un'armata di non-morti che non si stancano mai di faticare nei campi?",
    446: "Beh, come minimo ti chiederò di riparare le pentole che Corgon ha ridotto in pezzi!\n\nMa a parte questo, sei il benvenuto qui.\n\nE Sorin, se mi chiami ancora tuo Maestro, ricorda bene: abbiamo ancora tanto da imparare da questo mondo, per quanto lunghe possano essere le nostre vite."
}

def apply():
    print(f"Loading {KETTLE_FILE}...")
    wb = openpyxl.load_workbook(KETTLE_FILE)
    ws = wb.active
    
    headers = {ws.cell(1, c).value: c for c in range(1, ws.max_column + 1)}
    col_text = headers.get('text', 12)
    
    updated = 0
    for r, it_text in KETTLE_TRANSLATIONS.items():
        if r <= ws.max_row:
            ws.cell(r, col_text, it_text)
            updated += 1
            
    wb.save(KETTLE_FILE)
    print(f"Aggiornate con successo {updated} righe in kettle.xlsx")

if __name__ == '__main__':
    apply()
